```json
{
  "title": "మొక్కలు సూర్యకాంతిని ఆహారంగా ఉపయోగించుకోవడం",
  "key_idea": "మొక్కలు సూర్యకాంతి, నీరు, గాలిలోని కార్బన్ డై ఆక్సైడ్‌ను ఉపయోగించి నిజమైన ఆహారాన్ని తయారు చేస్తాయి.",
  "method": [
    "మొక్క యొక్క ఆకులలో ఆకుపచ్చ రంగు పదార్థం (క్లోరోఫిల్) ఉందని గుర్తించండి.",
    "సూర్యకాంతి ఆకుపచ్చ ఆకులను తాకినప్పుడు ఈ రంగు పదార్థం శక్తిని సంగ్రహిస్తుందని గుర్తించండి.",
    "మొక్క యొక్క మూలాలు నేల నుండి నీరను పీల్చుకుంటాయని మరియు ఎకువ భాగాన్ని ఆకుల వరకు పంపుతాయని చెప్పండి.",
    "గాలిలోని కార్బన్ డై ఆక్సైడ్ ఆకుల ద్వారా ప్రవేశిస్తుందని చెప్పండి.",
    "ఈ మూడూ కలిసి ఆకులలో చక్కెర (అంటే ఆహారం) ఆక్సిజన్‌గా మారుతుందని చెప్పండి."
  ],
  "worked_example": {
    "problem": "చెరకు మొక్కకు ఉదయం సూర్యకాంతి, నీరు, గాలి లభిస్తే ఏమవుతుంది?",
    "steps": [
      "ఆకులలోని ఆకుపచ్చ రంగు సూర్యకాంతిని గ్రహిస్తుంది.",
      "మూలాలు నేల నుండి నీరను తీసుకుంటాయి.",
      "గాలి ఆకుల ద్వారా కార్బన్ డై ఆక్సైడ్‌ను పంపుతుంది.",
      "ఈ మూడూ కలిసి ఆకులలో ఆహారం (చక్కెర) తయారవుతుంది."
    ],
    "answer": "చెరకు మొక్క తన సొంత ఆహారం తయారు చేసుకుంటుంది మరియు ఆకులు ఆకుపచ్చగా ఉండిపోయి, మొక్క శక్తిపై ఉండిపోతుంది."
  },
  "key_terms": [
    {
      "term": "ఫోటోసింథసిస్",
      "meaning": "మొక్కలు సూర్యకాంతిని ఉపయోగించి నిజమైన ఆహారం తయారు చేసుకునే ప్రక్రియ"
    },
    {
      "term": "క్లోరోఫిల్",
      "meaning": "ఆకులలోని ఆకుపచ్చ రంగు పదార్థం, ఇది సూర్యకాంతిని ఆకులకు సంపర్కం చేస్తుంది"
    },
    {
      "term": "కార్బన్ డై ఆక్సైడ్",
      "meaning": "గాలిలో ఉండే ఒక వాయువు, ఇది మొక్కలకు ఆహారం తయారు చేయడానికి అవసరం"
    }
  ],
  "common_mistakes": [
    "మొక్కలు నేల నుండి నేరుగా ఆహారం తీసుకుంటాయని భావించడం - నిజానికి మొక్కలు సూర్యకాంతిని ఉపయోగించి ఆహారం తయారు చేసుకోవాలి.",
    "ఆకుల రంగు ఆకుపచ్చగా ఉండటం కేవలం ఎందుకో తెలియనందుకు అనుకోవడం - ఆకుపచ్చ రంగు శక్తిని సంగ్రహిస్తుంది."
  ],
  "remember": "సూర్యకాంతి + నీరు + కార్బన్ డై ఆక్సైడ్ = ఆకులలో ఆహారం (చక్కెర) + ఆక్సిజన్",
  "quick_check": [
    {
      "q": "నీ ఇంటి బాగిలో పెరిగిన టమాటో మొక్కకు సూర్యకాంతి లేకపోతే ఏమవుతుంది?",
      "a": "సూర్యకాంతి లేనిదే, ఆకులు ఆకుపచ్చగా ఉండవు మరియు మొక్క నిజమైన ఆహారం తయారు చేయలేదు, కాబట్టి బలం లేకుండా ఏమీ వృద్ధి చేయలేదు."
    },
    {
      "q": "గుండ్రని కుండలో నీటితో పొడి మిట్టి ఉంచి, దానిలో విత్తనం నాటితే, కానీ సూర్యకాంతి ఇవ్వకపోతే, విత్తనం గుండ్లకుండా మొక్కగా గుండెలుకుంటుందా?",
      "a": "విత్తనం మొక్కగా గుండెలుకుంటుంది కానీ ఎటువంటి ఆకుపచ్చ ఆకులు లేకుండా, దీనిని హరితమైన పూర్ణ ఆహారం లేకుండా (శక్తి లేకుండా) సూర్యకాంతి సమయంలో ఆకుపచ్చ పూర్ణంగా ఎందుకు వచ్చినట్లుకుంటుందీ."
    }
  ],
  "tell_your_child": "ఇష్టకా, ఆకులు ఆకుపచ్చగా ఉండటానికి ఒక కారణం ఉంది - అది సూర్యకాంతిని పట్టుకుని ఆహారం తయారు చేయటానికి సాయపడుతుంది. మీ మొక్కను ఎక్కువ సూర్యకాంతిని ఇస్తే, అది మరింత బలవంతంగా పెరుగుతుంది."
}
```
